import{_ as e,o as a,c as i,a3 as t}from"./chunks/framework.CpLciM8b.js";const c=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md","lastUpdated":1785946507000}'),n={name:"guide/cli.md"};function l(r,s,h,o,p,d){return a(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p><code>@flakemetry/cli</code> sends results and inspects configuration from any CI provider or a local shell. Run it with <code>npx flakemetry &lt;command&gt;</code> or install it as a dev dependency.</p><p>All commands read <code>FLAKEMETRY_ENDPOINT</code> and <code>FLAKEMETRY_TOKEN</code> from the environment; <code>--endpoint</code> and <code>--token</code> override them.</p><h2 id="flakemetry-run-command" tabindex="-1"><code>flakemetry run -- &lt;command&gt;</code> <a class="header-anchor" href="#flakemetry-run-command" aria-label="Permalink to &quot;`flakemetry run -- &lt;command&gt;`&quot;">​</a></h2><p>Runs a test command, uploads whatever the reporter wrote, and exits with the command&#39;s own code.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Two guarantees, and they are the reason to use this over two separate steps:</p><ul><li><strong>The wrapped command&#39;s exit code is the exit code.</strong> A failing suite still fails the build.</li><li><strong>An upload problem never changes that.</strong> A dead endpoint, an expired token or a network blip warns on stderr and leaves the build&#39;s verdict alone. Observability must not become a source of CI failures.</li></ul><p>Results are uploaded whether the suite passed or failed — they are most worth having when it failed.</p><p>If no results file exists, it says so and does nothing. Wrapping a suite whose reporter is not configured yet is ordinary, not an error.</p><h2 id="flakemetry-flaky" tabindex="-1"><code>flakemetry flaky</code> <a class="header-anchor" href="#flakemetry-flaky" aria-label="Permalink to &quot;`flakemetry flaky`&quot;">​</a></h2><p>Lists flaky tests for the project, worst first. Needs a token with the <strong><code>read</code></strong> scope — see the <a href="/flakemetry/v/2026-09-30/reference/api">read API</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flaky</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flaky</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quarantined</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flaky</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --min-score</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @acme/web</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flaky</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[] | select(.score &gt; 0.8) | .title&#39;</span></span></code></pre></div><p><code>--json</code> prints the rows unchanged, for scripting.</p><h2 id="flakemetry-quarantine" tabindex="-1"><code>flakemetry quarantine</code> <a class="header-anchor" href="#flakemetry-quarantine" aria-label="Permalink to &quot;`flakemetry quarantine`&quot;">​</a></h2><p>Quarantines a test so it stops failing the build, releases one, or hands it back to the scorer. Needs a token with the <strong><code>quarantine</code></strong> scope.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quarantine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">testIdentityI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reason</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;known bad, tracked in JIRA-123&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quarantine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">testIdentityI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quarantine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">testIdentityI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auto</span></span></code></pre></div><p>Its own scope, deliberately. Quarantining is the one call that can hide a real regression, so neither a token that reads a dashboard nor the one pasted into every CI job in the company gets to make that decision.</p><p><strong>A person&#39;s decision sticks.</strong> While a test is quarantined or released by hand, the scorer stops moving it — in both directions. Otherwise the next run would silently undo you: a manually quarantined test that the scorer does not consider flaky gets released, and a manually released test that it does gets quarantined again.</p><p><code>--auto</code> gives the test back. The current state is left alone and the scorer takes over from the next run: the cooldown that decides when a quarantined test is safe to release needs run history, and guessing here would be a second copy of that rule, free to drift from the first.</p><h2 id="flakemetry-doctor" tabindex="-1"><code>flakemetry doctor</code> <a class="header-anchor" href="#flakemetry-doctor" aria-label="Permalink to &quot;`flakemetry doctor`&quot;">​</a></h2><p>Checks the configuration file, the endpoint, whether it answers, and what the token is allowed to do.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ endpoint: https://flakemetry.internal</span></span>\n<span class="line"><span>✓ reachable: answered 200</span></span>\n<span class="line"><span>✓ token: present (fmk_…037e)</span></span>\n<span class="line"><span>! read scope: valid token without the read scope — uploads will work, queries will not</span></span></code></pre></div><p>The token is always redacted: this is the command people paste into a chat when something is wrong.</p><p>A missing <strong>read</strong> scope is a warning, not a failure, and <code>doctor</code> still exits <code>0</code> — an upload-only token is a perfectly good CI setup, and failing would break the pipeline that has one. Only a missing endpoint, an unreachable server or a rejected token exit non-zero.</p><h2 id="flakemetry-upload-file" tabindex="-1"><code>flakemetry upload [file]</code> <a class="header-anchor" href="#flakemetry-upload-file" aria-label="Permalink to &quot;`flakemetry upload [file]`&quot;">​</a></h2><p>Uploads a reporter output file (default <code>flakemetry-results.json</code>) — the JSON a native reporter writes when <code>FLAKEMETRY_OUTPUT_FILE</code> is set. Use this to split the test step from the delivery step in CI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FLAKEMETRY_OUTPUT_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">flakemetry-results.json</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flakemetry-results.json</span></span></code></pre></div><p>The upload is skipped (not failed) when no endpoint or token is set, so it is safe to leave in a pipeline that sometimes runs without credentials.</p><h2 id="flakemetry-junit-file" tabindex="-1"><code>flakemetry junit [file]</code> <a class="header-anchor" href="#flakemetry-junit-file" aria-label="Permalink to &quot;`flakemetry junit [file]`&quot;">​</a></h2><p>Parses a JUnit XML report (default <code>junit.xml</code>) and uploads it — the path for any runner without a native reporter. See <a href="/flakemetry/v/2026-09-30/guide/junit">Any runner via JUnit XML</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --junitxml=junit.xml</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> junit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> junit.xml</span></span></code></pre></div><p>Pass <code>--fail-on-error</code> to make the step exit non-zero on a delivery failure; by default it never breaks the build.</p><h2 id="flakemetry-import-directory" tabindex="-1"><code>flakemetry import &lt;directory&gt;</code> <a class="header-anchor" href="#flakemetry-import-directory" aria-label="Permalink to &quot;`flakemetry import &lt;directory&gt;`&quot;">​</a></h2><p>Seeds history from an archive of JUnit XML reports, so the flaky board is useful on the first day instead of after a fortnight of new runs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./ci-artifacts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # see what would be sent</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./ci-artifacts</span></span></code></pre></div><p>Every <code>.xml</code> file under the directory becomes one run:</p><ul><li><strong>Ordered oldest first.</strong> Scoring is incremental and stamps first-seen dates as it goes, so a newest-first import would date every test to the end of its own history.</li><li><strong>Each report gets its own commit</strong>, derived from the report&#39;s bytes. Scoring reads &quot;same commit, different result&quot; as a flakiness signal, and one shared sha across months of history would manufacture that signal for every test in the archive.</li><li><strong>Re-running is safe.</strong> Idempotency keys are derived from each file&#39;s path and contents, so an interrupted import resumes and a repeated one changes nothing.</li><li><strong>Timestamps</strong> come from the report&#39;s <code>timestamp</code> attribute, then the manifest, then the file&#39;s modification time.</li></ul><p>Reports carry no commit or branch of their own. When you know them, pass a manifest:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ci-artifacts/2026-05-01.xml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;commitSha&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;9fceb02&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;branch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./ci-artifacts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history.json</span></span></code></pre></div><p>Anything unparseable or empty is named on stderr rather than dropped quietly.</p><h2 id="flakemetry-config" tabindex="-1"><code>flakemetry config</code> <a class="header-anchor" href="#flakemetry-config" aria-label="Permalink to &quot;`flakemetry config`&quot;">​</a></h2><p>Prints the resolved configuration and where each value came from — the config file (if any), environment, and whether a token is present (redacted). Add <code>--json</code> for machine output.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>',45)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
